// Commands generated by the app run on the SSH server's POSIX shell. Exercise
// that syntax on Windows with Git for Windows, without changing it to cmd syntax.
import { existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { execFileSync } from "node:child_process";

function resolveShell() {
  const override = process.env.ORIATUNNEL_TEST_SH;
  if (override) return override;
  if (process.platform !== "win32") return "/bin/sh";
  const gitCore = execFileSync("git", ["--exec-path"], {
    encoding: "utf8",
  }).trim();
  const candidates = [
    resolve(gitCore, "../../../bin/sh.exe"),
    resolve(dirname(gitCore), "../../usr/bin/sh.exe"),
  ];
  const shell = candidates.find(existsSync);
  if (!shell)
    throw new Error(
      "POSIX command tests require Git for Windows or ORIATUNNEL_TEST_SH pointing to sh.exe.",
    );
  return shell;
}

export const posixShell = resolveShell();
